import {listingStatusLabel} from "@/lib/listing-status";
﻿import Link from "next/link";import {Car,PlusCircle} from "lucide-react";import {requireVendor} from "@/lib/auth";import {connectMongoose} from "@/lib/db";import {VendorProfileModel} from "@/models/VendorProfile";import {VehicleModel} from "@/models/Vehicle";import {money} from "@/lib/utils";export default async function Page(){const user=await requireVendor();await connectMongoose();const vendor=await VendorProfileModel.findOne({userId:user.id}).select("_id").lean();const cars=vendor?await VehicleModel.find({vendorId:vendor._id}).sort({createdAt:-1}).select("title status price slug").lean():[];return <div><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-bold">Your listings</h2><p className="mt-1 text-sm text-[#68756f]">Track admin reviews, approved listings, and sold vehicles.</p></div><Link href="/vendor/cars/new" className="btn btn-dark"><PlusCircle size={16}/>Add a car</Link></div>{cars.length?<div className="mt-6 grid gap-3">{cars.map(car=><Link href={`/vendor/cars/${car._id}`} className="card flex flex-wrap items-center justify-between gap-4 p-5 hover:border-[#79a28f]" key={String(car._id)}><div><b>{car.title}</b><p className="mt-1 text-sm text-[#68756f]">{money(car.price)}</p></div><span className={`pill ${car.status==="ACTIVE"?"bg-green-100 text-green-800":car.status==="REJECTED"?"bg-red-100 text-red-800":"bg-amber-100 text-amber-800"}`}>{listingStatusLabel(car.status)}</span></Link>)}</div>:<div className="card mt-6 p-10 text-center"><Car className="mx-auto text-[#4c7865]"/><h3 className="mt-4 text-xl font-bold">Add your first car</h3><p className="mt-2 text-[#68756f]">Add your car details and photos, then submit the listing for admin approval.</p><Link href="/vendor/cars/new" className="btn btn-primary mt-6">Create listing</Link></div>}</div>}

